// frontend/src/App.js
import React from "react";
import { BrowserRouter as Router, Route, Routes } from "react-router-dom";
import GoatList from "./components/GoatList";
import AddGoat from "./components/AddGoat";
import EditGoat from "./components/EditGoat";

const App = () => {
  return (
    <Router>
      <Routes>
        <Route path="/" element={<GoatList />} />
        <Route path="/add-goat" element={<AddGoat />} />
        <Route path="/edit-goat/:id" element={<EditGoat />} />
      </Routes>
    </Router>
  );
};

export default App;
