// frontend/src/components/GoatList.js
import React, { useEffect, useState } from "react";
import axios from "axios";

const GoatList = () => {
  const [goats, setGoats] = useState([]);

  useEffect(() => {
    fetchGoats();
  }, []);

  const fetchGoats = async () => {
    const response = await axios.get("http://localhost:8000/api/goats/");
    setGoats(response.data);
  };

  const deleteGoat = async (id) => {
    if (window.confirm("Are you sure you want to delete this goat?")) {
      await axios.delete(`http://localhost:8000/api/goats/${id}/`);
      fetchGoats();
    }
  };

  return (
    <div>
      <h1>Goat List</h1>
      <button onClick={() => (window.location.href = "/add-goat")}>
        Add Goat
      </button>
      <table>
        <thead>
          <tr>
            <th>ID</th>
            <th>Name</th>
            <th>Age</th>
            <th>Breed</th>
            <th>Actions</th>
          </tr>
        </thead>
        <tbody>
          {goats.map((goat) => (
            <tr key={goat.id}>
              <td>{goat.id}</td>
              <td>{goat.name}</td>
              <td>{goat.age}</td>
              <td>{goat.breed}</td>
              <td>
                <button
                  onClick={() =>
                    (window.location.href = `/edit-goat/${goat.id}`)
                  }
                >
                  Edit
                </button>
                <button onClick={() => deleteGoat(goat.id)}>Delete</button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
};

export default GoatList;
