// frontend/src/components/EditGoat.js
import React, { useEffect, useState } from "react";
import axios from "axios";
import { useParams } from "react-router-dom";

const EditGoat = () => {
  const { id } = useParams();
  const [formData, setFormData] = useState({ name: "", age: "", breed: "" });

  useEffect(() => {
    fetchGoat();
  }, []);

  const fetchGoat = async () => {
    const response = await axios.get(`http://localhost:8000/api/goats/${id}/`);
    setFormData(response.data);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    await axios.put(`http://localhost:8000/api/goats/${id}/`, formData);
    window.location.href = "/";
  };

  return (
    <div>
      <h1>Edit Goat</h1>
      <form onSubmit={handleSubmit}>
        <label>Name:</label>
        <input
          type="text"
          value={formData.name}
          onChange={(e) => setFormData({ ...formData, name: e.target.value })}
          required
        />
        <label>Age:</label>
        <input
          type="number"
          value={formData.age}
          onChange={(e) => setFormData({ ...formData, age: e.target.value })}
          required
        />
        <label>Breed:</label>
        <input
          type="text"
          value={formData.breed}
          onChange={(e) => setFormData({ ...formData, breed: e.target.value })}
          required
        />
        <button type="submit">Save</button>
      </form>
    </div>
  );
};

export default EditGoat;
